for t in range(int(input())):
	n = int(input())
	a = list(map(int, input().split()))
	if n % 2 == 1:
		print('NO')
		continue
	f = 1
	for i in range(n // 2):
		if a[i] == -1 and a[i + n // 2] == -1:
			a[i] = a[i + n // 2] = 1
		elif a[i] == -1:
			a[i] = a[i + n // 2]
		elif a[i + n // 2] == -1:
			a[i + n // 2] = a[i]
		elif a[i] != a[i + n // 2]:
			f = 0
			break
	if f == 1:
		print('YES')
		for i in range(n):
			print(a[i], end=' ')
		print()
	else:
		print('NO')
